DECLARE @AMMEX_GP_Extenal_ID__c CHAR(51) = TRIM(?),
		@SFTextValue CHAR(255) = TRIM(?);

IF @AMMEX_GP_Extenal_ID__c <> ''
BEGIN
    DECLARE @FieldName char(31) = 'Location/Member #',
        	@EXTENDER_FIELD_ID int = NULL;

    ------------------------Find the ID of the FIELD Above---------------
    SELECT 
    	@EXTENDER_FIELD_ID=Field_ID
    FROM 
    	EXT20010 --STORES ALL FIELD DETAILS
    WHERE 
    	EXT20010.FIELDNAM LIKE '%'+RTRIM(@FieldName)+'%';

    IF @EXTENDER_FIELD_ID IS NULL
    BEGIN
        raiserror('Field ID for [Location/Member #] is not found.', 16,2);
    END;
    ---------------------------------------------------------------------


    ----------Find if there are any Record of Customer from Source Data in WINDOW_ID above------------------
    /*DECLARE @EXTENDER_RECORD_ID BIGINT = NULL,
            @EXTENDER_WINDOW_ID char(15) = 'CUSTOMER'

    SELECT 
        @EXTENDER_RECORD_ID = Extender_Record_ID
    FROM 
        EXT01100 WITH(NOLOCK) --STORES ALL RECORDS IN EXTENDER TABLE
    WHERE 
        Extender_Window_ID = RTRIM(@EXTENDER_WINDOW_ID) 
    	AND Extender_Key_Values_1 = RTRIM(@AMMEX_GP_Extenal_ID__c)

    IF @EXTENDER_RECORD_ID IS NULL
    BEGIN
        INSERT INTO EXT01100 (
            Extender_Record_ID,
            Extender_Window_ID,
            Extender_Key_Values_1,
            Extender_Key_Values_2,
            Extender_Key_Values_3,
            Extender_Key_Values_4,
            Extender_Key_Values_5,
            NOTEINDX,
            MODIFDT,
            MDFUSRID,
            CREATDDT,
            CRUSRId
        )
        VALUES(
            (SELECT MAX(Extender_Record_ID) + 1 FROM EXT01100),                     -- Extender_Record_ID
            RTRIM(@EXTENDER_WINDOW_ID),                       -- Extender_Window_ID
            RTRIM(@AMMEX_GP_Extenal_ID__c),                -- Extender_Key_Values_1
            '',                              -- Extender_Key_Values_2
            '',                              -- Extender_Key_Values_3
            '',                                        -- Extender_Key_Values_4
            '',                                        -- Extender_Key_Values_5
            '0.00',                                    -- NOTEINDX
            DATEADD(d,DATEDIFF(d,0,getdate()),0),      -- MODIFDT
            'BOOMI',                                      -- MDFUSRID
            DATEADD(d,DATEDIFF(d,0,getdate()),0),      -- CREATDDT
            'BOOMI'                                   -- CRUSRId
        )

        SELECT 
            @EXTENDER_RECORD_ID = Extender_Record_ID
        FROM 
            EXT01100 WITH(NOLOCK)
        WHERE 
            Extender_Window_ID = RTRIM(@EXTENDER_WINDOW_ID) 
            AND Extender_Key_Values_1 = RTRIM(@AMMEX_GP_Extenal_ID__c)
    END	*/

    DECLARE @EXTENDER_RECORD_ID BIGINT = NULL,
        @EXTENDER_WINDOW_ID CHAR(15) = 'CUSTOMER',
        @USRID CHAR(15) = 'BOOMI',
        @RetryCount INT = 0,
        @MaxRetries INT = 3;

    WHILE @RetryCount < @MaxRetries
    BEGIN
        BEGIN TRY

            SET @EXTENDER_RECORD_ID = NULL;

            EXEC CREATE_EXTENDER_HEADER 
                @EXTENDER_WINDOW_ID,
                @AMMEX_GP_Extenal_ID__c,
                '',
                '',
                '',
                '',
                @USRID,
                @EXTENDER_RECORD_ID OUTPUT;

            IF @EXTENDER_RECORD_ID IS NULL
            BEGIN
                THROW 50001, 'Extender Record ID is null', 1;
            END

            BREAK;

        END TRY
        BEGIN CATCH

            SET @RetryCount += 1;

            IF @RetryCount >= @MaxRetries
            BEGIN
                THROW;
            END

            WAITFOR DELAY '00:00:02';

        END CATCH;
    END;
    ---------------------------------------------------------------------------------------------------------

    DECLARE @CUSTOMER_EXTENDER_FIELD_ID BIGINT = NULL;

    ----------Find if there are any Record of Customer in String Field Table (EXT01101) from Extender Table WINDOW_ID above------------------
    SELECT
    	@CUSTOMER_EXTENDER_FIELD_ID = Extender_Record_Id
    FROM 
    	EXT01101
    WHERE
    	Extender_Record_Id = @EXTENDER_RECORD_ID
    	AND Field_ID = @EXTENDER_FIELD_ID;

    -------------------------UPSERT RECORD [Location/Member #]--------------------
    IF @CUSTOMER_EXTENDER_FIELD_ID IS NULL
    BEGIN
        INSERT INTO EXT01101 (Extender_Record_ID,Field_ID,STRGA255)
    		VALUES(@EXTENDER_RECORD_ID,@EXTENDER_FIELD_ID,@SFTextValue);
    END
    ELSE
    BEGIN
    	UPDATE EXT01101 
    	    SET STRGA255=RTRIM(@SFTextValue)
    	WHERE 
    		Extender_Record_ID=@EXTENDER_RECORD_ID
    		AND Field_ID=@EXTENDER_FIELD_ID;
    END;
    -------------------------------------------------------------------------
END;

