            IF @RetryCount >= @MaxRetries
            BEGIN
                THROW;
            END

            WAITFOR DELAY '00:00:02';

        END CATCH;
    END;
    ---------------------------------------------------------------------------------------------------------

    EXEC EXTENDER_UPSERT_EXT01103 @EXTENDER_RECORD_ID,@EXTENDER_FIELD_ID,@Checkbox;
END;

DECLARE @AMMEX_GP_Extenal_ID__c CHAR(51) = TRIM(?),
		@Picklist_Value CHAR(133) = TRIM(?),
		@Price_Change CHAR(133) = TRIM(?);

IF @AMMEX_GP_Extenal_ID__c<>''
BEGIN
    ----------Find if there are any Record of Customer from Source Data in WINDOW_ID above------------------
    /*DECLARE @EXTENDER_RECORD_ID BIGINT = NULL,
            @EXTENDER_WINDOW_ID char(15) = 'CUSTOMER2'

    SELECT 
        @EXTENDER_RECORD_ID = Extender_Record_ID
    FROM 
        EXT01100 WITH(NOLOCK) --STORES ALL RECORDS IN EXTENDER TABLE
    WHERE 
        Extender_Window_ID = RTRIM(@EXTENDER_WINDOW_ID) 
    	AND Extender_Key_Values_1 = RTRIM(@AMMEX_GP_Extenal_ID__c)

    IF @EXTENDER_RECORD_ID IS NULL
    BEGIN
        INSERT INTO EXT01100 (
            Extender_Record_ID,
            Extender_Window_ID,
            Extender_Key_Values_1,
            Extender_Key_Values_2,
            Extender_Key_Values_3,
            Extender_Key_Values_4,
            Extender_Key_Values_5,
            NOTEINDX,
            MODIFDT,
            MDFUSRID,
            CREATDDT,
            CRUSRId
        )
        VALUES(
            (SELECT MAX(Extender_Record_ID) + 1 FROM EXT01100),                     -- Extender_Record_ID
            RTRIM(@EXTENDER_WINDOW_ID),                       -- Extender_Window_ID
            RTRIM(@AMMEX_GP_Extenal_ID__c),                -- Extender_Key_Values_1
            '',                              -- Extender_Key_Values_2
            '',                              -- Extender_Key_Values_3
            '',                                        -- Extender_Key_Values_4
            '',                                        -- Extender_Key_Values_5
            '0.00',                                    -- NOTEINDX
            DATEADD(d,DATEDIFF(d,0,getdate()),0),      -- MODIFDT
            'BOOMI',                                      -- MDFUSRID
            DATEADD(d,DATEDIFF(d,0,getdate()),0),      -- CREATDDT
            'BOOMI'                                   -- CRUSRId
        )

        SELECT 
            @EXTENDER_RECORD_ID = Extender_Record_ID
        FROM 
            EXT01100 WITH(NOLOCK)
        WHERE 
            Extender_Window_ID = RTRIM(@EXTENDER_WINDOW_ID) 
            AND Extender_Key_Values_1 = RTRIM(@AMMEX_GP_Extenal_ID__c)
    END	*/

    DECLARE @EXTENDER_RECORD_ID BIGINT = NULL,
        @EXTENDER_WINDOW_ID CHAR(15) = 'CUSTOMER2',
        @USRID CHAR(15) = 'BOOMI',
        @RetryCount INT = 0,
        @MaxRetries INT = 3;

    WHILE @RetryCount < @MaxRetries
    BEGIN
        BEGIN TRY

            SET @EXTENDER_RECORD_ID = NULL;

            EXEC CREATE_EXTENDER_HEADER 
                @EXTENDER_WINDOW_ID,
                @AMMEX_GP_Extenal_ID__c,
                '',
                '',
                '',
                '',
                @USRID,
                @EXTENDER_RECORD_ID OUTPUT;

            IF @EXTENDER_RECORD_ID IS NULL
            BEGIN
                THROW 50001, 'Extender Record ID is null', 1;
            END

            BREAK;

        END TRY
        BEGIN CATCH

            SET @RetryCount += 1;

            IF @RetryCount >= @MaxRetries
            BEGIN
                THROW;
            END

            WAITFOR DELAY '00:00:02';

        END CATCH;
    END;
    ---------------------------------------------------------------------------------------------------------

    ------------------------Find the ID of the FIELD Above---------------

    DECLARE @FieldName char(31) = 'Do Not Sell Reason',
        	@DNS_EXTENDER_FIELD_ID int = NULL;
    SELECT 
    	@DNS_EXTENDER_FIELD_ID=Field_ID
    FROM 
    	EXT20010 --STORES ALL FIELD DETAILS
    WHERE 
    	EXT20010.FIELDNAM LIKE '%'+@FieldName+'%';

    IF @DNS_EXTENDER_FIELD_ID IS NULL
    BEGIN
        raiserror('Field ID for [Do Not Sell Reason] is not found.', 16,2);
    END;
    ---------------------------------------------------------------------

    ---------------Find the ID of the Picklist Value from Source Data---------------

    DECLARE @DNS_Picklist_List_ID int = NULL;

    IF @Picklist_Value='' OR @Picklist_Value IS NULL
    BEGIN
        SET @Picklist_Value = '(blank)';
    END;

    SELECT 
        @DNS_Picklist_List_ID=Extender_List_Item_ID
    FROM 
    	EXT20021
    	INNER JOIN EXT20010 ON EXT20021.Extender_List_ID = EXT20010.Extender_List_ID
    WHERE 
    	STRNG132 LIKE '%'+@Picklist_Value+'%'
    	AND EXT20010.Field_ID=@DNS_EXTENDER_FIELD_ID;

    IF @DNS_Picklist_List_ID IS NULL
    BEGIN
        raiserror('[Do Not Sell Reason] option is not found in the Picklist', 16,2);
    END;

	----------Stored Procedure to UPSERT Picklist in any Extender Table/Window------------
    EXEC EXTENDER_UPSERT_EXT01103 @EXTENDER_RECORD_ID,@DNS_EXTENDER_FIELD_ID,@DNS_Picklist_List_ID;
    --------------------------------------------------------------------------------------


    -------------------------------------------------------------------------------------------------------------------------
    IF @Price_Change<>'' AND @Price_Change IS NOT NULL
	BEGIN
		DECLARE @Price_Change_EXTENDER_FIELD_ID int = NULL;

		SELECT 
			@Price_Change_EXTENDER_FIELD_ID=Field_ID
		FROM 
			EXT20010 --STORES ALL FIELD DETAILS
		WHERE 
			EXT20010.FIELDNAM='Price Change Notice';

		IF @Price_Change_EXTENDER_FIELD_ID IS NULL
		BEGIN
			raiserror('Field ID for [Price Change Notice] is not found.', 16,2);
		END;

		/*IF @Price_Change='' OR @Price_Change IS NULL
		BEGIN
			SET @Price_Change = '(blank)';
		END;*/

		DECLARE @Price_Change_Picklist_List_ID int = NULL;

		SELECT 
			@Price_Change_Picklist_List_ID=Extender_List_Item_ID
		FROM 
			EXT20021
			INNER JOIN EXT20010 ON EXT20021.Extender_List_ID = EXT20010.Extender_List_ID
		WHERE 
			STRNG132 LIKE '%'+@Price_Change+'%'
			AND EXT20010.Field_ID=@Price_Change_EXTENDER_FIELD_ID;

		IF @Price_Change_Picklist_List_ID IS NULL
		BEGIN
			raiserror('[Price Change Notice] option is not found in the Picklist', 16,2);
		END;

		EXEC EXTENDER_UPSERT_EXT01103 @EXTENDER_RECORD_ID,@Price_Change_EXTENDER_FIELD_ID,@Price_Change_Picklist_List_ID;
	END
    -------------------------------------------------------------------------------------------------------------------------
END;

