------Find if there are any Record of ItemNumber in String Field Table (EXT01101) from WINDOW_ID above--- SELECT @STRING_EXTENDER_FIELD_ID = Extender_Record_Id FROM EXT01101 WHERE Extender_Record_Id = @EXTENDER_RECORD_ID AND Field_ID = @EXTENDER_FIELD_ID
-------------------------UPSERT RECORD------------------------------- IF @STRING_EXTENDER_FIELD_ID IS NULL BEGIN INSERT INTO EXT01101 (Extender_Record_ID,Field_ID,STRGA255) VALUES(@EXTENDER_RECORD_ID,@EXTENDER_FIELD_ID,@StringValue) END ELSE BEGIN UPDATE EXT01101 SET STRGA255=RTRIM(@StringValue) WHERE Extender_Record_ID=@EXTENDER_RECORD_ID AND Field_ID=@EXTENDER_FIELD_ID END ------------------------------------------------------------------------- END

